"use strict";
const pageTemplates = {
  "audit-log": "<div class=\"grid grid-3 mb-section\">\n    {{events_stat}}{{failed_stat}}{{users_stat}}\n  </div>\n  <section class=\"panel table-panel\">\n    <div class=\"table-toolbar\">\n      <div>\n        <div class=\"eyebrow\">Admin only</div>\n        <h3>Account and record activity</h3>\n      </div>\n      <div class=\"segmented\" aria-label=\"Activity filter\">{{filters}}</div>\n    </div>\n    {{table}}\n  </section>\n  <p class=\"footer-note\">\n    Shows the latest 500 events. Passwords and clinical inputs are never\n    written to the audit log.\n  </p>",
  "audit-filter": "<button data-audit-filter=\"{{key}}\" class=\"{{active_class}}\">\n    {{label}}\n  </button>",
  "audit-table": "<div class=\"table-responsive\">\n    <table class=\"records-table audit-table\">\n      <thead>\n        <tr>\n          <th>Time</th>\n          <th>User</th>\n          <th>Role</th>\n          <th>Activity</th>\n          <th>Details</th>\n        </tr>\n      </thead>\n      <tbody>\n        {{rows}}\n      </tbody>\n    </table>\n  </div>",
  "audit-row": "<tr class=\"{{row_class}}\">\n    <td>{{time}}</td>\n    <td><b>{{username}}</b></td>\n    <td>{{role}}</td>\n    <td><span class=\"audit-action {{action_class}}\">{{action}}</span></td>\n    <td>{{detail}}</td>\n  </tr>",
  "confirm-dialog": "<dialog id=\"confirm-modal\" class=\"confirm-modal\" aria-labelledby=\"confirm-title\">\n    <form id=\"confirm-form\" novalidate>\n      <div class=\"confirm-icon\">{{warning_icon}}</div>\n      <h2 id=\"confirm-title\">{{title}}</h2>\n      <p>{{body}}</p>\n      {{error}}\n      <label class=\"form-label\" for=\"confirm-password\">Enter your password to continue</label>\n      <input class=\"form-control\" id=\"confirm-password\" name=\"password\" type=\"password\" autocomplete=\"current-password\" maxlength=\"100\" required />\n      <div class=\"confirm-actions\">\n        <button type=\"button\" class=\"btn btn-outline-secondary\" id=\"confirm-cancel\">Cancel</button>\n        <button type=\"submit\" class=\"btn btn-danger\" id=\"confirm-submit\">{{confirm_label}}</button>\n      </div>\n    </form>\n  </dialog>",
  "dashboard-source-switch": "<div class=\"context-row\">\n    <span class=\"source-pill\"> <span class=\"dot\"> </span>{{source_label}}</span>\n    <div class=\"segmented\" aria-label=\"Analytics source\">\n      <button data-source=\"dataset\" class=\"{{dataset_active}}\">\n        Dataset overview\n      </button>\n      <button data-source=\"screenings\" class=\"{{screenings_active}}\">\n        My screenings\n      </button>\n    </div>\n  </div>",
  "dashboard-stats": "<div class=\"grid grid-4 mb-section\">\n    {{record_stat}}{{label_stat}}{{recall_stat}}{{auc_stat}}\n  </div>",
  "dashboard-records-link": "<button class=\"link-button\" data-nav=\"patients\">\n    View all screened patients {{icon_1}}\n  </button>",
  "dashboard": "<div class=\"grid grid-major\">{{throughput_panel}}{{importance_panel}}</div>\n  <div class=\"section-label\">Risk factor analysis</div>\n  <div class=\"grid grid-3\">{{glucose_panel}}{{bmi_panel}}{{smoking_panel}}</div>\n  <div class=\"grid grid-major mt-4\">{{age_panel}}{{recent_panel}}</div>\n  <div class=\"grid grid-2 mt-4\">{{residence_panel}}{{work_panel}}</div>",
  "dashboard-throughput-legend": "<div class=\"legend\">\n    <span> <i style=\"background: #f57930\"> </i>{{records_label}}</span>\n    <span> <i style=\"background: #d94d15\"> </i>{{positives_label}}</span>\n  </div>",
  "dashboard-importance-note": "<p class=\"chart-caption\">\n    Permutation importance: change in test ROC-AUC. Near-zero values indicate\n    little measured predictive signal.\n  </p>",
  "dashboard-smoking-legend": "<div class=\"legend\">{{legend_items}}</div>",
  "dashboard-smoking-legend-item": "<span> <i style=\"background:{{color}}\"> </i>{{label}} {{share}}</span>",
  "help": "<div class=\"settings-wrap stack\">\n    {{getting_started_panel}}{{source_panel}}{{interpretation_panel}}{{technology_panel}}\n  </div>",
  "help-getting-started": "<div class=\"notice\">\n    <strong>1. New screening</strong>\n    <br />Complete all model fields. Use Unknown for unavailable smoking status\n    and BMI unavailable when it is missing.<br />\n    <br />\n    <strong>2. Predict & review</strong>\n    <br />The Python classifier returns a model score, a threshold label, and\n    signed feature contributions.<br />\n    <br />\n    <strong>3. Save the screening</strong>\n    <br />Saving writes the scored profile and its model version to SQLite.\n    Refreshing or restarting does not remove it.<br />\n    <br />\n    <strong>4. Explore the population</strong>\n    <br />Search and filter saved records, export CSV, review individual\n    explanations, and mark follow-up status.\n  </div>",
  "help-data-source": "<p class=\"small muted\" style=\"line-height: 1.9\">\n    Mohammed Borhan Uddin (2025), Mendeley Data, version 1. {{record_count}}\n    synthetic records; {{positive_count}} positive labels; {{missing_bmi_count}}\n    missing BMI values. Provided under CC BY 4.0 according to the proposal.\n  </p>\n  <a\n    class=\"link-button\"\n    href=\"https://doi.org/10.17632/s2nh6fm925.1\"\n    target=\"_blank\"\n    rel=\"noopener noreferrer\"\n    >View dataset attribution {{external_icon}}</a\n  >\n  <div class=\"notice mt-3\">\n    The dataset contains no patient names, screening dates, or screening sites.\n    The app does not fabricate these for the source population.\n  </div>",
  "help-interpretation": "<div class=\"notice orange\">{{limitations}}</div>\n  <p class=\"chart-caption mt-3\">\n    The proposal's recall target is 70%; model performance reports the measured\n    result even when that target is not achieved. A high accuracy alone can be\n    misleading in this imbalanced dataset.\n  </p>",
  "help-limitation": "<p class=\"mb-3\">{{limitation}}</p>",
  "help-technology": "<div class=\"notice\">\n    Streamlit hosts the app and Python model. HTML, CSS, Bootstrap, and vanilla\n    JavaScript provide the interface. Pandas and NumPy prepare the data;\n    scikit-learn, imbalanced-learn SMOTE, and XGBoost train the models. SQLite\n    stores saved screenings.\n  </div>",
  "login": "<main class=\"login-screen\" id=\"content\" tabindex=\"-1\">\n    <span class=\"login-bubble b1\" aria-hidden=\"true\"></span>\n    <span class=\"login-bubble b2\" aria-hidden=\"true\"></span>\n    <span class=\"login-bubble b3\" aria-hidden=\"true\"></span>\n    <span class=\"login-bubble b4\" aria-hidden=\"true\"></span>\n    <section class=\"login-card\" aria-labelledby=\"login-title\">\n      <div class=\"login-art\" aria-hidden=\"true\">\n        <svg class=\"login-art-shape\" viewBox=\"0 0 600 560\" preserveAspectRatio=\"none\">\n          <path d=\"M0 0H470C525 55 565 125 545 205C525 285 468 305 478 385C488 465 560 500 556 560H0Z\" />\n        </svg>\n        <div class=\"login-brand\">CEREBRA</div>\n        <div class=\"login-illustration\">\n          <span class=\"art-blob\"></span>\n          <span class=\"art-blob inner\"></span>\n          <span class=\"art-dot d1\"></span>\n          <span class=\"art-dot d2\"></span>\n          <span class=\"art-dot d3\"></span>\n          <span class=\"art-dot d4\"></span>\n          <img src=\"assets/logo.png\" alt=\"\" />\n        </div>\n        <p class=\"login-copyright\">\n          © 2026 CEREBRA · Stroke Analytics<br />Research prototype\n        </p>\n      </div>\n      <div class=\"login-form-side\">\n        <h1 id=\"login-title\">Login</h1>\n        <form id=\"login-form\" novalidate>\n          {{notice}}\n          {{error}}\n          <div class=\"login-field\">\n            <label for=\"login-username\">Username</label>\n            <input\n              class=\"form-control\"\n              id=\"login-username\"\n              name=\"username\"\n              value=\"{{username}}\"\n              placeholder=\"Enter your username\"\n              autocomplete=\"username\"\n              maxlength=\"100\"\n              required\n              {{disabled}}\n            />\n          </div>\n          <div class=\"login-field\">\n            <label for=\"login-password\">Password</label>\n            <div class=\"password-input\">\n              <input\n                class=\"form-control\"\n                id=\"login-password\"\n                name=\"password\"\n                type=\"password\"\n                placeholder=\"Enter your password\"\n                autocomplete=\"current-password\"\n                maxlength=\"100\"\n                required\n                {{disabled}}\n              />\n              <button\n                type=\"button\"\n                class=\"password-toggle\"\n                id=\"password-toggle\"\n                aria-label=\"Show password\"\n                aria-pressed=\"false\"\n              >\n                {{eye_icon}}\n              </button>\n            </div>\n          </div>\n          <button class=\"btn btn-primary login-submit\" type=\"submit\" {{disabled}}>\n            {{submit_icon}} {{submit_label}}\n          </button>\n        </form>\n        <p class=\"login-note\">\n          No account yet? <b>Ask your administrator.</b>\n        </p>\n        <p class=\"login-disclaimer\">Not a clinical diagnostic tool.</p>\n      </div>\n    </section>\n  </main>",
  "model-stats": "<div class=\"grid grid-4 mb-section\">\n    {{accuracy_stat}}{{precision_stat}}{{recall_stat}}{{f1_stat}}\n  </div>",
  "model-confusion-matrix": "<div class=\"cm-grid\">{{cells}}</div>\n  <p class=\"chart-caption\">\n    {{test_count}} test records · {{positive_count}} positive labels · fixed 50%\n    threshold. Recall target ≥ 70%: <strong>{{recall_status}}</strong>.\n  </p>",
  "model-confusion-cell": "<div class=\"cm-cell {{error_class}}\">\n    <label>{{label}}</label>\n    <strong>{{count}}</strong>\n    <small>{{note}}</small>\n  </div>",
  "model-results-table": "<div class=\"table-responsive\">\n    <table class=\"metric-table\">\n      <thead>\n        <tr>\n          <th>Candidate</th>\n          {{headers}}\n        </tr>\n      </thead>\n      <tbody>\n        {{rows}}\n      </tbody>\n    </table>\n  </div>",
  "model-results-heading": "<th>{{label}}</th>",
  "model-results-row": "<tr class=\"{{selected_class}}\">\n    <td>{{model_name}}{{active_label}}</td>\n    {{metrics}}\n  </tr>",
  "model-results-value": "<td>{{value}}</td>",
  "model-selector": "<div class=\"context-row\">\n    <span class=\"source-pill\">\n      <span class=\"dot\"> </span>HELD-OUT TEST SET · {{test_count}} RECORDS</span\n    >\n    <label class=\"d-flex align-items-center gap-2 small muted\"\n      >Inspect model<select class=\"form-select\" id=\"model-select\">\n        <option value=\"all\">All models</option>\n        {{model_options}}\n      </select>\n    </label>\n  </div>",
  "model-option": "<option {{selected}}>{{model_name}}</option>",
  "model-detail": "<div class=\"grid grid-2\">{{comparison_panel}}{{matrix_panel}}</div>\n  <div class=\"mt-4\">{{evidence_panel}}</div>\n  <div class=\"grid grid-2 mt-4\">{{roc_panel}}{{precision_recall_panel}}</div>\n  <div class=\"mt-4\">{{protocol_panel}}</div>",
  "model-legend": "<div class=\"legend justify-content-center\">{{legend_items}}</div>",
  "model-legend-item": "<span> <i style=\"background:{{color}}\"> </i>{{model_name}}</span>",
  "model-protocol": "<div class=\"grid grid-2\">\n    <div>{{protocol_rows}}</div>\n    <div class=\"notice\">\n      <strong>{{model_name}}</strong> was selected using validation recall, with\n      F1 and ROC-AUC as tie-breakers. Test results were measured afterward.<br />\n      <br />Median imputation, scaling, and one-hot encoding are fitted on\n      training rows. SMOTE never touches validation or test rows. Plain SMOTE\n      can produce fractional encoded categories, as noted in your PDF; this\n      remains an exploratory limitation.<br />\n      <br />Model version: <strong>{{model_version}}</strong>\n    </div>\n  </div>\n  <button class=\"btn btn-outline-secondary mt-3\" id=\"export-report\">\n    {{download_icon}} Download evaluation JSON\n  </button>",
  "model-protocol-row": "<div class=\"mini-row\">\n    <span>{{label}}</span>\n    <b>{{value}}</b>\n  </div>",
  "models-table": "<div class=\"table-responsive\">\n    <table class=\"metric-table all-models-table\">\n      <thead>\n        <tr>\n          <th>Model</th>\n          {{headers}}\n        </tr>\n      </thead>\n      <tbody>\n        {{rows}}\n      </tbody>\n    </table>\n  </div>",
  "models-table-row": "<tr class=\"{{selected_class}}\">\n    <td><strong>{{model_name}}</strong>{{model_status}}</td>\n    {{metrics}}\n  </tr>",
  "models-confusion-matrix": "<div class=\"cm-grid\">{{cells}}</div>\n  <p class=\"chart-caption\">\n    Recall target ≥ 70%: <strong>{{recall_status}}</strong> · ROC-AUC\n    {{roc_auc}}\n  </p>",
  "models-selector": "<div class=\"context-row\">\n    <span class=\"source-pill\">\n      <span class=\"dot\"> </span>SAME HELD-OUT TEST SET · {{test_count}}\n      RECORDS</span\n    >\n    <label class=\"d-flex align-items-center gap-2 small muted\"\n      >Inspect model<select class=\"form-select\" id=\"model-select\">\n        <option value=\"all\" selected>All models</option>\n        {{model_options}}\n      </select>\n    </label>\n  </div>",
  "models-comparison-note": "<p class=\"chart-caption mt-3\">\n    All {{model_count}} evaluated models use the same test records and a 50%\n    classification threshold. The active model was selected using validation\n    recall; accuracy alone does not establish predictive usefulness.\n  </p>",
  "models-overview": "<div class=\"mt-4\">{{comparison_panel}}</div>\n  <div class=\"section-label\">Classification outcomes · all models</div>\n  <div class=\"grid grid-2\">{{matrices}}</div>\n  <button class=\"btn btn-outline-secondary mt-4\" id=\"export-report\">\n    {{download_icon}} Download evaluation JSON\n  </button>",
  "notification-row": "<article class=\"notification-row {{pending_class}}\"{{row_attributes}}>\n    <span class=\"notification-symbol\">{{item_icon}}</span>\n    <div class=\"notification-copy\">\n      <h3>{{title}}</h3>\n      <p>{{description}}</p>\n      <small>Screened {{screened_date}}</small>{{screening_link}}\n    </div>\n  </article>",
  "notification-screening-link": "<button class=\"link-button\" data-patient=\"{{patient_id}}\">\n    View screening {{arrow_icon}}\n  </button>",
  "notification-summary": "<section\n    class=\"notifications\"\n    id=\"notification-summary\"\n    aria-label=\"Notifications summary\"\n  >\n    <h3>Notifications</h3>\n    <p class=\"small muted\">\n      {{pending_count}} follow-ups pending · {{screening_count}} saved\n      screenings\n    </p>\n    <div class=\"notification-preview\">{{preview_rows}}</div>\n    <p class=\"small muted\">Model evaluation is available.</p>\n    <button class=\"link-button\" data-nav=\"notifications\">\n      View all notifications {{arrow_icon}}\n    </button>\n  </section>",
  "notifications": "<div class=\"notifications-page stack\">\n    <div class=\"grid grid-3\">\n      {{screenings_stat}}{{pending_stat}}{{updates_stat}}\n    </div>\n    <section class=\"panel\">\n      <div class=\"notification-toolbar\">\n        <div>\n          <div class=\"eyebrow\">Activity center</div>\n          <h2>All notifications</h2>\n          <p class=\"small muted mt-2\">\n            Latest screenings first, with current follow-up status.\n          </p>\n        </div>\n        <div class=\"segmented\" aria-label=\"Filter notifications\">\n          {{filters}}\n        </div>\n      </div>\n      <div class=\"notification-list\">{{activity_rows}}{{workspace_update}}</div>\n    </section>\n  </div>",
  "notifications-filter": "<button\n    data-notification-filter=\"{{filter_key}}\"\n    class=\"{{active_class}}\"\n    aria-pressed=\"{{pressed}}\"\n  >\n    {{label}}\n  </button>",
  "notifications-model-update": "<article class=\"notification-row\">\n    <span class=\"notification-symbol\">{{model_icon}}</span>\n    <div class=\"notification-copy\">\n      <h3>Model evaluation available</h3>\n      <p>\n        Review measured results for {{model_name}} and compare all evaluated\n        models.\n      </p>\n      <button class=\"link-button\" data-nav=\"model\">\n        View model performance {{arrow_icon}}\n      </button>\n    </div>\n  </article>",
  "population-stats": "<div class=\"grid grid-4 mb-section\">\n    {{share_stat}}{{sites_stat}}{{flagged_stat}}{{glucose_stat}}\n  </div>",
  "population-glucose": "{{glucose}}<span style=\"font-size: 13px\"> mg/dL</span>",
  "population-site-row": "<div class=\"site-row\">\n    <div class=\"site-labels\">\n      <div><span class=\"site-index\">{{rank}}</span>{{site_name}}</div>\n      <small\n        >{{screening_count}} screened ·\n        <strong style=\"color: var(--orange)\">{{high_share}} high label</strong>\n      </small>\n    </div>\n    <div class=\"site-track\">\n      <span style=\"width:{{bar_width}}%\"> </span>\n    </div>\n  </div>",
  "population-no-sites": "<p class=\"chart-caption mt-3\">\n    Descriptive counts of saved screenings. Site comparisons are not population\n    prevalence estimates and may reflect small or unequal samples.\n  </p>",
  "population-health": "<div class=\"grid grid-3 mt-4\">\n    {{follow_up_panel}}{{hypertension_panel}}{{source_panel}}\n  </div>\n  <div class=\"grid grid-2 mt-4\">{{age_panel}}{{residence_panel}}</div>",
  "population-follow-up": "<div class=\"stat-value\" style=\"color: var(--orange)\">{{pending_count}}</div>\n  <p class=\"small muted\">High-label records not yet marked as contacted.</p>\n  <button class=\"link-button\" id=\"view-pending\">\n    Review records {{arrow_icon}}\n  </button>",
  "population-hypertension": "<div class=\"stat-value\">{{hypertension_share}}</div>\n  <p class=\"small muted\">\n    {{hypertension_count}} of {{high_count}} saved high-label profiles.\n  </p>",
  "population-source-note": "<div class=\"notice\">\n    This view uses <strong>{{screening_count}} saved screenings</strong>. The\n    50,000 synthetic source records are available separately on the dashboard.\n  </div>",
  "risk-breakdown": "<div class=\"grid breakdown-layout\">\n    <section class=\"panel\">\n      <div class=\"eyebrow\">Select patient</div>\n      <p class=\"small muted mb-3\">{{screening_count}} saved screenings</p>\n      <div class=\"patient-list\">{{patient_list}}</div>\n    </section>\n    <div class=\"stack\">\n      {{overview_panel}}{{explanation_panel}}\n      <div\n        class=\"panel d-flex justify-content-between align-items-center gap-3 flex-wrap\"\n      >\n        <div>\n          <h3>Follow-up status</h3>\n          <p class=\"small muted mt-2\">{{follow_up_status}}</p>\n        </div>\n        <button\n          class=\"btn btn-outline-secondary\"\n          id=\"follow-up\"\n          data-id=\"{{patient_id}}\"\n          data-contacted=\"{{contacted_value}}\"\n          {{disabled}}\n        >\n          {{follow_up_icon}}{{follow_up_label}}\n        </button>\n      </div>\n      {{admin_panel}}\n    </div>\n  </div>",
  "breakdown-profile": "<div class=\"patient-overview\">\n    {{gauge}}\n    <div class=\"patient-overview-info\">\n      <div class=\"d-flex align-items-center flex-wrap gap-2\">\n        <h2>{{participant_name}}</h2>\n        {{risk_badge}}\n      </div>\n      <p class=\"small muted mt-2\">{{patient_id}} · age {{age}}</p>\n      <div class=\"detail-grid\">{{detail_rows}}</div>\n    </div>\n  </div>",
  "breakdown-detail-row": "<div>\n    <label>{{label}}</label>\n    <p>{{value}}</p>\n  </div>",
  "breakdown-admin": "<div class=\"panel record-admin d-flex justify-content-between align-items-center gap-3 flex-wrap\">\n    <div>\n      <h3>Delete this record</h3>\n      <p class=\"small muted mt-2\">Admin only. Removes the screening for every user.</p>\n    </div>\n    <button class=\"btn btn-outline-danger\" id=\"delete-screening\" {{disabled}}>\n      {{trash_icon}} Delete record\n    </button>\n  </div>",
  "prediction-input": "<div class=\"form-group\">\n    <label class=\"form-label\" for=\"{{key}}\">{{label}}</label>\n    <input\n      class=\"form-control\"\n      id=\"{{key}}\"\n      name=\"{{key}}\"\n      type=\"{{type}}\"\n      value=\"{{value}}\"\n      {{attributes}}\n      placeholder=\"{{placeholder}}\"\n    />\n  </div>",
  "prediction-select": "<div class=\"form-group\">\n    <label class=\"form-label\" for=\"{{key}}\">{{label}}</label>\n    <select\n      id=\"{{key}}\"\n      name=\"{{key}}\"\n      class=\"form-select\"\n      required\n    >\n      <option value=\"\" disabled {{placeholder_selected}}>\n        Select {{placeholder_label}}…\n      </option>\n      {{options}}\n    </select>\n  </div>",
  "prediction-option": "<option value=\"{{value}}\" {{selected}}>{{label}}</option>",
  "prediction-binary": "<div class=\"form-group\">\n    <div class=\"form-label\" id=\"label-{{key}}\">{{label}}</div>\n    <div class=\"binary\" role=\"radiogroup\" aria-labelledby=\"label-{{key}}\">\n      {{options}}\n    </div>\n  </div>",
  "prediction-binary-option": "<label>\n    <input name=\"{{key}}\" type=\"radio\" value=\"{{value}}\" required {{checked}} />\n    <span>{{label}}</span>\n  </label>",
  "risk-prediction": "<div class=\"grid prediction-grid\">\n    <section class=\"panel\">\n      <div class=\"form-intro\">\n        <div class=\"eyebrow\">\n          {{prediction_icon}} &nbsp; Risk prediction module\n        </div>\n        <h2>Patient health profile</h2>\n        <p>\n          Enter a profile to run the trained classifier. Review the model score\n          and its contributing factors, then save the screening to your\n          workspace.\n        </p>\n      </div>\n      <form id=\"prediction-form\">\n        {{name_field}}\n        <div class=\"row\">\n          <div class=\"col-6\">{{age_field}}</div>\n          <div class=\"col-6\">{{gender_field}}</div>\n        </div>\n        <div class=\"row\">\n          <div class=\"col-6\">{{glucose_field}}</div>\n          <div class=\"col-6\">\n            {{bmi_field}}<label class=\"form-check-label mb-3\">\n              <input\n                class=\"form-check-input me-2\"\n                type=\"checkbox\"\n                id=\"bmi_missing\"\n                name=\"bmi_missing\"\n                {{bmi_missing_checked}}\n              />BMI unavailable</label\n            >\n          </div>\n        </div>\n        <div class=\"row\">\n          <div class=\"col-6\">{{hypertension_field}}</div>\n          <div class=\"col-6\">{{heart_disease_field}}</div>\n        </div>\n        <div class=\"row\">\n          <div class=\"col-6\">{{married_field}}</div>\n          <div class=\"col-6\">{{smoking_field}}</div>\n        </div>\n        <div class=\"row\">\n          <div class=\"col-6\">{{work_field}}</div>\n          <div class=\"col-6\">{{residence_field}}</div>\n        </div>\n        {{site_field}}\n        <div id=\"form-error\">{{form_error}}</div>\n        <div class=\"d-flex gap-2 flex-wrap mt-4\">\n          <button class=\"btn btn-primary\" type=\"submit\" {{submit_disabled}}>\n            {{submit_icon}}{{submit_label}}\n          </button>\n          <button\n            class=\"btn btn-outline-secondary\"\n            type=\"button\"\n            id=\"reset-form\"\n            {{reset_disabled}}\n          >\n            {{reset_icon}} Reset\n          </button>\n        </div>\n        <p class=\"chart-caption mt-4\">\n          Supported input ranges follow the supplied dataset. Missing BMI uses\n          the training median ({{bmi_median}}). Gender categories reflect the\n          source data. Name and site are not model features.\n        </p>\n      </form>\n    </section>\n    <div class=\"stack\" id=\"prediction-results\">{{results}}</div>\n  </div>",
  "prediction-error": "<div class=\"form-error\" role=\"alert\">{{message}}</div>",
  "prediction-result": "<div class=\"result-body\">\n    {{gauge}}{{risk_badge}}\n    <h2 class=\"result-name\">{{participant_name}}</h2>\n    <p>\n      {{score_description}} The label does not establish or rule out medical\n      risk.\n    </p>\n    <div class=\"prediction-details\">{{model_name}} · SMOTE · threshold 50%</div>\n    <button id=\"save-screening\" class=\"btn {{save_class}}\" {{save_disabled}}>\n      {{save_icon}}{{save_label}}</button\n    >{{records_link}}\n  </div>",
  "prediction-records-link": "<button class=\"link-button\" data-nav=\"patients\">\n    Open screened patients {{arrow_icon}}\n  </button>",
  "prediction-model-context": "<div class=\"mini-row\">\n    <span>Training source</span>\n    <b>50,000 synthetic records</b>\n  </div>\n  <div class=\"mini-row\">\n    <span>Class balancing</span>\n    <b>Training-only SMOTE</b>\n  </div>\n  <div class=\"mini-row\">\n    <span>Label threshold</span>\n    <b>50% model score</b>\n  </div>\n  <div class=\"mini-row\">\n    <span>Clinical validation</span>\n    <b>Not established</b>\n  </div>\n  <div class=\"notice orange mt-3\">\n    This system is for academic research. Model scores are not calibrated\n    estimates of a person's likelihood of stroke. Do not use them to make\n    clinical decisions.\n  </div>",
  "screened-patients": "<section class=\"panel table-panel\">\n    <div class=\"table-toolbar\">\n      <div>\n        <div class=\"eyebrow mb-2\">Screened patients</div>\n        <h2 id=\"record-count\">{{record_count}} records</h2>\n      </div>\n      <div class=\"table-tools\">\n        <div class=\"search-box\">\n          {{search_icon}}<input\n            class=\"form-control\"\n            id=\"patient-search\"\n            value=\"{{query}}\"\n            placeholder=\"Name or patient ID…\"\n            aria-label=\"Filter by name or patient ID\"\n          />\n        </div>\n        <div class=\"segmented\" aria-label=\"Risk filter\">{{risk_filters}}</div>\n        <div class=\"date-filter\">\n          <button\n            class=\"btn btn-outline-secondary\"\n            id=\"date-toggle\"\n            aria-expanded=\"{{date_expanded}}\"\n          >\n            {{calendar_icon}}{{date_label}}</button\n          >{{date_popover}}\n        </div>\n        <button\n          class=\"icon-button\"\n          id=\"extra-filters\"\n          aria-label=\"More filters\"\n          aria-expanded=\"{{filters_expanded}}\"\n        >\n          {{filter_icon}}\n        </button>\n        <button\n          class=\"icon-button\"\n          id=\"export-csv\"\n          aria-label=\"Export filtered records as CSV\"\n          title=\"Export filtered records as CSV\"\n        >\n          {{download_icon}}\n        </button>\n      </div>\n    </div>\n    {{extra_filters}}\n    <div id=\"patients-table\">{{patient_table}}</div>\n  </section>\n  <p class=\"chart-caption mt-3\">\n    Select a record to view its saved model explanation. Labels describe the\n    model cutoff; they are not diagnoses. Screening dates use Asia/Manila.\n  </p>",
  "patients-risk-filter": "<button class=\"{{active_class}}\" data-risk=\"{{risk_label}}\">{{label}}</button>",
  "patients-date-popover": "<div class=\"date-popover\">\n    <div class=\"eyebrow\">Quick select</div>\n    <div class=\"quick-dates\">{{date_presets}}</div>\n    <div class=\"eyebrow\">Custom range</div>\n    <form id=\"date-form\">\n      <div class=\"row g-2 mb-3\">\n        <div class=\"col-6\">\n          <label class=\"form-label\" for=\"date-from\">From</label>\n          <input\n            type=\"date\"\n            class=\"form-control\"\n            id=\"date-from\"\n            name=\"from\"\n            value=\"{{from_date}}\"\n            required\n          />\n        </div>\n        <div class=\"col-6\">\n          <label class=\"form-label\" for=\"date-to\">To</label>\n          <input\n            type=\"date\"\n            class=\"form-control\"\n            id=\"date-to\"\n            name=\"to\"\n            value=\"{{to_date}}\"\n            required\n          />\n        </div>\n      </div>\n      <button class=\"btn btn-primary w-100\" type=\"submit\">Apply</button>\n    </form>\n  </div>",
  "patients-date-preset": "<button class=\"{{active_class}}\" data-date=\"{{date_key}}\">{{label}}</button>",
  "patients-extra-filters": "<div class=\"filter-options\">\n    <label\n      >Site<select id=\"site-filter\" class=\"form-select\">\n        {{site_options}}\n      </select>\n    </label>\n    <label\n      >Smoking<select id=\"smoking-filter\" class=\"form-select\">\n        {{smoking_options}}\n      </select>\n    </label>\n    <button class=\"btn btn-outline-secondary\" id=\"clear-filters\">\n      Clear filters\n    </button>\n  </div>",
  "patients-site-option": "<option {{selected}}>{{site}}</option>",
  "patients-table": "<div class=\"table-responsive\">\n    <table class=\"records-table\">\n      <thead>\n        <tr>\n          {{headers}}\n        </tr>\n      </thead>\n      <tbody>\n        {{rows}}\n      </tbody>\n    </table>\n  </div>\n  <div class=\"table-footer\">\n    <span\n      >Showing {{first_record}}–{{last_record}} of {{matched_count}} matched\n      records · {{total_count}} total</span\n    >\n    <div class=\"d-flex gap-2 align-items-center\">\n      {{pagination}}<span class=\"micro\">EXPERIMENTAL · THRESHOLD 50%</span>\n    </div>\n  </div>",
  "patients-table-heading": "<th scope=\"col\">{{label}}</th>",
  "patients-table-row": "<tr\n    tabindex=\"0\"\n    data-patient=\"{{patient_id}}\"\n    aria-label=\"View {{accessible_name}}\"\n  >\n    <td>\n      <div class=\"patient-name\">{{participant_name}}</div>\n      <div class=\"patient-id\">{{display_id}}</div>\n      <div class=\"record-date\">{{screened_date}}</div>\n    </td>\n    <td>{{age}}</td>\n    <td>{{glucose}}<span class=\"micro muted\"> mg/dL</span></td>\n    <td>{{bmi}}</td>\n    <td>\n      {{hypertension_badge}}{{heart_disease_badge}}{{no_conditions_badge}}\n    </td>\n    <td>{{smoking_status}}</td>\n    <td>{{married}}</td>\n    <td>{{work_type}}</td>\n    <td>{{residence}}</td>\n    <td class=\"score-cell {{risk_class}}\">{{score}}</td>\n    <td>{{risk_badge}}</td>\n  </tr>",
  "patients-pagination": "<button\n    class=\"btn btn-outline-secondary\"\n    data-page-step=\"-1\"\n    {{previous_disabled}}\n  >\n    Previous\n  </button>\n  <span>{{current_page}} / {{total_pages}}</span>\n  <button\n    class=\"btn btn-outline-secondary\"\n    data-page-step=\"1\"\n    {{next_disabled}}\n  >\n    Next\n  </button>",
  "settings": "<div class=\"settings-wrap stack\">\n    {{account_panel}}{{appearance_panel}}{{storage_panel}}\n  </div>",
  "settings-appearance": "<div class=\"settings-row\">\n    <div>\n      <h3>Color theme</h3>\n      <p>Switch between the light and dark designs.</p>\n    </div>\n    <div class=\"segmented\">\n      <button data-theme=\"light\" class=\"{{light_active}}\">\n        {{sun_icon}} Light\n      </button>\n      <button data-theme=\"dark\" class=\"{{dark_active}}\">\n        {{moon_icon}} Dark\n      </button>\n    </div>\n  </div>",
  "settings-account": "<div class=\"settings-row\">\n    <div class=\"account-summary\">\n      <span class=\"avatar\">{{initials}}</span>\n      <div>\n        <h3>{{display_name}}</h3>\n        <p>{{username}} · <span class=\"role-badge {{role}}\">{{role_label}}</span> · {{site_label}}</p>\n      </div>\n    </div>\n    <button class=\"btn btn-outline-secondary\" id=\"sign-out\" {{disabled}}>\n      {{sign_out_icon}} Sign out\n    </button>\n  </div>\n  <form id=\"password-form\" class=\"settings-row password-form\" novalidate>\n    <div>\n      <h3>Change password</h3>\n      <p>Use at least 8 characters. You stay signed in after changing it.</p>\n    </div>\n    <div class=\"password-fields\">\n      <input class=\"form-control\" name=\"current\" type=\"password\" placeholder=\"Current password\" aria-label=\"Current password\" autocomplete=\"current-password\" maxlength=\"100\" required {{disabled}} />\n      <input class=\"form-control\" name=\"new\" type=\"password\" placeholder=\"New password\" aria-label=\"New password\" autocomplete=\"new-password\" minlength=\"8\" maxlength=\"100\" required {{disabled}} />\n      <input class=\"form-control\" name=\"confirm\" type=\"password\" placeholder=\"Confirm new password\" aria-label=\"Confirm new password\" autocomplete=\"new-password\" minlength=\"8\" maxlength=\"100\" required {{disabled}} />\n      <button class=\"btn btn-primary\" type=\"submit\" {{disabled}}>Update password</button>\n    </div>\n  </form>",
  "settings-storage": "<div class=\"mini-row\">\n    <span>Saved screenings</span>\n    <b>{{screening_count}}</b>\n  </div>\n  <div class=\"mini-row\">\n    <span>Database</span>\n    <b>SQLite · local workspace</b>\n  </div>\n  <div class=\"mini-row\">\n    <span>Timezone</span>\n    <b>Asia/Manila</b>\n  </div>\n  <div class=\"notice mt-3\">\n    Clinical inputs and saved explanations are stored in the local database.\n    Browser storage contains appearance preferences only. Use research aliases\n    for demonstrations.\n  </div>\n  <div class=\"d-flex gap-2 mt-3\">\n    <button\n      class=\"btn btn-outline-secondary\"\n      id=\"refresh-data\"\n      {{refresh_disabled}}\n    >\n      {{refresh_icon}} Refresh records\n    </button>\n    <button class=\"btn btn-outline-secondary\" data-nav=\"patients\">\n      Open records\n    </button>\n  </div>",
  "system": "<div class=\"grid grid-4 mb-section\">\n    {{model_stat}}{{records_stat}}{{accounts_stat}}{{backups_stat}}\n  </div>\n  <section class=\"panel table-panel\">\n    <div class=\"table-toolbar\">\n      <div>\n        <div class=\"eyebrow\">Admin only</div>\n        <h3>Database backups</h3>\n      </div>\n      <button class=\"btn btn-primary\" id=\"create-backup\" {{disabled}}>\n        {{backup_icon}} Create backup now\n      </button>\n    </div>\n    <p class=\"small muted backup-note\">\n      Each backup is a full copy of screenings, accounts, and the audit log,\n      saved on this computer in <code>{{folder}}</code>. Restoring first saves\n      the current data as a new backup, so it can be undone.\n    </p>\n    {{table}}\n  </section>\n  <div class=\"mt-4\">{{model_panel}}</div>",
  "backup-table": "<div class=\"table-responsive\">\n    <table class=\"records-table backup-table\">\n      <thead>\n        <tr>\n          <th>Backup</th>\n          <th>Created</th>\n          <th>Size</th>\n          <th>Screenings</th>\n          <th>Accounts</th>\n          <th></th>\n        </tr>\n      </thead>\n      <tbody>\n        {{rows}}\n      </tbody>\n    </table>\n  </div>",
  "backup-row": "<tr>\n    <td><b>{{name}}</b>{{safety_tag}}</td>\n    <td>{{created}}</td>\n    <td>{{size}}</td>\n    <td>{{screenings}}</td>\n    <td>{{users}}</td>\n    <td class=\"text-end\">\n      <button class=\"btn btn-outline-secondary btn-sm\" data-restore=\"{{name}}\" {{disabled}}>Restore</button>\n    </td>\n  </tr>",
  "users": "<div class=\"grid grid-4 mb-section\">\n    {{accounts_stat}}{{admins_stat}}{{workers_stat}}{{disabled_stat}}\n  </div>\n  {{create_panel}}\n  <section class=\"panel table-panel mt-4\">\n    <div class=\"table-toolbar\">\n      <div>\n        <div class=\"eyebrow\">Admin only</div>\n        <h3>Accounts</h3>\n      </div>\n      <p class=\"small muted\">\n        Healthcare workers only see screenings from their assigned site.\n      </p>\n    </div>\n    <div class=\"table-responsive\">\n      <table class=\"records-table users-table\">\n        <thead>\n          <tr>\n            <th>Account</th>\n            <th>Role</th>\n            <th>Site</th>\n            <th>Status</th>\n            <th>Created</th>\n            <th></th>\n          </tr>\n        </thead>\n        <tbody>\n          {{rows}}\n        </tbody>\n      </table>\n    </div>\n  </section>\n  <datalist id=\"site-options\">{{site_options}}</datalist>",
  "user-create": "<form id=\"user-create-form\" class=\"user-form\" novalidate>\n    <div class=\"form-group\">\n      <label class=\"form-label\" for=\"new-username\">Username</label>\n      <input class=\"form-control\" id=\"new-username\" name=\"username\" value=\"{{username}}\" maxlength=\"40\" autocomplete=\"off\" required {{disabled}} />\n    </div>\n    <div class=\"form-group\">\n      <label class=\"form-label\" for=\"new-display-name\">Display name</label>\n      <input class=\"form-control\" id=\"new-display-name\" name=\"display_name\" value=\"{{display_name}}\" maxlength=\"60\" required {{disabled}} />\n    </div>\n    <div class=\"form-group\">\n      <label class=\"form-label\" for=\"new-role\">Role</label>\n      <select class=\"form-select\" id=\"new-role\" name=\"role\" data-site-target=\"new-site\" {{disabled}}>\n        {{role_options}}\n      </select>\n    </div>\n    <div class=\"form-group\">\n      <label class=\"form-label\" for=\"new-site\">Site</label>\n      <input class=\"form-control\" id=\"new-site\" name=\"site\" value=\"{{site}}\" list=\"site-options\" maxlength=\"100\" placeholder=\"{{site_placeholder}}\" {{site_disabled}} />\n    </div>\n    <div class=\"form-group\">\n      <label class=\"form-label\" for=\"new-password\">Initial password</label>\n      <input class=\"form-control\" id=\"new-password\" name=\"password\" type=\"password\" minlength=\"8\" maxlength=\"100\" autocomplete=\"new-password\" placeholder=\"At least 8 characters\" required {{disabled}} />\n    </div>\n    <button class=\"btn btn-primary\" type=\"submit\" {{disabled}}>{{plus_icon}} Create account</button>\n  </form>",
  "user-row": "<tr class=\"{{row_class}}\">\n    <td>\n      <div class=\"patient-name\">{{display_name}}{{you_label}}</div>\n      <div class=\"record-date\">{{username}}</div>\n    </td>\n    <td><span class=\"role-badge {{role}}\">{{role_label}}</span></td>\n    <td>{{site}}</td>\n    <td><span class=\"status-badge {{status_class}}\">{{status}}</span></td>\n    <td>{{created}}</td>\n    <td class=\"text-end\">\n      <button class=\"btn btn-outline-secondary btn-sm\" data-edit-user=\"{{id}}\" aria-expanded=\"{{editing}}\">\n        {{edit_label}}\n      </button>\n    </td>\n  </tr>\n  {{edit_row}}",
  "user-edit": "<tr class=\"user-edit-row\">\n    <td colspan=\"6\">\n      <form id=\"user-edit-form\" class=\"user-form\" data-user-id=\"{{id}}\" novalidate>\n        <div class=\"form-group\">\n          <label class=\"form-label\" for=\"edit-display-name\">Display name</label>\n          <input class=\"form-control\" id=\"edit-display-name\" name=\"display_name\" value=\"{{display_name}}\" maxlength=\"60\" required {{disabled}} />\n        </div>\n        <div class=\"form-group\">\n          <label class=\"form-label\" for=\"edit-role\">Role</label>\n          <select class=\"form-select\" id=\"edit-role\" name=\"role\" data-site-target=\"edit-site\" {{self_disabled}}>\n            {{role_options}}\n          </select>\n        </div>\n        <div class=\"form-group\">\n          <label class=\"form-label\" for=\"edit-site\">Site</label>\n          <input class=\"form-control\" id=\"edit-site\" name=\"site\" value=\"{{site}}\" list=\"site-options\" maxlength=\"100\" placeholder=\"{{site_placeholder}}\" {{site_disabled}} />\n        </div>\n        <div class=\"form-group\">\n          <label class=\"form-label\" for=\"edit-password\">Reset password</label>\n          <input class=\"form-control\" id=\"edit-password\" name=\"password\" type=\"password\" minlength=\"8\" maxlength=\"100\" autocomplete=\"new-password\" placeholder=\"Leave blank to keep\" {{disabled}} />\n        </div>\n        <label class=\"user-active\">\n          <input type=\"checkbox\" name=\"active\" {{active_checked}} {{self_disabled}} />\n          Account active\n        </label>\n        <div class=\"user-edit-actions\">\n          <button class=\"btn btn-primary\" type=\"submit\" {{disabled}}>Save changes</button>\n          <button class=\"btn btn-outline-secondary\" type=\"button\" data-edit-user=\"{{id}}\">Cancel</button>\n        </div>\n        {{self_note}}\n      </form>\n    </td>\n  </tr>"
};
